// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GatorToken {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferTaxRate() external view returns (uint16);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55Da3b152F48378A42D091be1eef2af37964BE45;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal() to get tokens
        // Label addresses for clarity
        vm.label(TARGET, "GatorToken");
        vm.label(address(0x000000000000000000000000000000000000dEaD), "BURN_ADDRESS");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get some Gator tokens first
        uint256 initialBalance = 1000 * 10**18;
        deal(TARGET, attacker, initialBalance);

        // Get initial total supply
        uint256 initialTotalSupply = GatorToken(TARGET).totalSupply();

        // Get initial balance of BURN_ADDRESS
        uint256 initialBurnBalance = GatorToken(TARGET).balanceOf(address(0x000000000000000000000000000000000000dEaD));

        // Transfer some tokens to BURN_ADDRESS
        uint256 burnAmount = 100 * 10**18;
        GatorToken(TARGET).transfer(address(0x000000000000000000000000000000000000dEaD), burnAmount);

        // Get final total supply
        uint256 finalTotalSupply = GatorToken(TARGET).totalSupply();

        // Get final balance of BURN_ADDRESS
        uint256 finalBurnBalance = GatorToken(TARGET).balanceOf(address(0x000000000000000000000000000000000000dEaD));

        // Verify the vulnerability:
        // 1. Total supply should have decreased by burnAmount but didn't
        // 2. BURN_ADDRESS balance increased by burnAmount
        assertEq(finalTotalSupply, initialTotalSupply, "Total supply should remain unchanged (vulnerability!)");
        assertEq(finalBurnBalance, initialBurnBalance + burnAmount, "BURN_ADDRESS should have received the tokens");

        // Also verify attacker balance decreased
        uint256 finalAttackerBalance = GatorToken(TARGET).balanceOf(attacker);
        assertEq(finalAttackerBalance, initialBalance - burnAmount, "Attacker balance should have decreased");
        assertEq(GatorToken(TARGET).totalSupply(), GatorToken(TARGET).totalSupply(), "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

